86	+  /// Calls `entries-list` (`ApiClient.get`) with `limit` always sent, and
87	+  /// `cursor` only when non-null (spec-4-1's own convention for an
88	+  /// optional-in-the-contract query parameter, mirroring [create]'s own
89	+  /// `mediaDurationSeconds` handling). Returns the raw page as a record —
90	+  /// no dedicated DTO wrapper type, since `EntriesRepositoryImpl.list()` is
91	+  /// this record's only reader.
92	+  Future<Either<Failure, ({List<EntryDto> items, String? nextCursor})>> list({
93	+    String? cursor,
94	+    int limit = 20,
95	+  }) async {
96	+    final result = await _apiClient.get(
97	+      'entries-list',
98	+      queryParameters: {'limit': limit, 'cursor': ?cursor},
99	+    );
100	+    return result.flatMap((json) {
101	+      try {
102	+        final data = json['data'] as List<dynamic>;
103	+        final items = data
104	+            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
105	+            .toList();
106	+        final meta = json['meta'] as Map<String, dynamic>;
107	+        final nextCursor = meta['nextCursor'] as String?;
108	+        return right((items: items, nextCursor: nextCursor));
109	+      } catch (error) {
110	+        // Same client-side-parse-failure rationale as `create()` above.
111	+        return left(Failure.malformedResponse(message: error.toString()));
112	+      }
113	+    });
114	+  }
115	 }
