151	+            await _entriesBox.put(dto.id, dto.toJson());
152	+          }
153	+        } catch (error) {
154	+          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
155	+          // thrown Hive/disk exception must never escape unmapped.
156	+          return left(Failure.malformedResponse(message: error.toString()));
157	+        }
158	+        return right(
159	+          EntriesPage(
160	+            items: page.items.map(_toEntry).toList(),
161	+            nextCursor: page.nextCursor,
