1957	+import 'entry.dart';
1958	+
1959	+/// One calendar day's worth of entries — [date] is truncated to midnight
1960	+/// *local* time (never UTC, never [Entry.createdAt]; Boundaries), so two
1961	+/// entries whose [Entry.occurredAt] fall on the same local day always land
1962	+/// in the same group regardless of the UTC offset the backend sent them in.
1963	+class EntryDateGroup {
1964	+  const EntryDateGroup({required this.date, required this.entries});
1965	+
1966	+  /// Always a `DateTime` with zeroed time-of-day fields (`DateTime(y, m,
1967	+  /// d)`) — day-label formatting ("Hoje"/"Ontem"/a date string) is
1968	+  /// presentation's job (Boundaries), not this pure entity's.
1969	+  final DateTime date;
1970	+
1971	+  final List<Entry> entries;
1972	+
1973	+  @override
1974	+  bool operator ==(Object other) =>
1975	+      identical(this, other) ||
1976	+      (other is EntryDateGroup &&
1977	+          other.date == date &&
1978	+          _listEquals(other.entries, entries));
1979	+
1980	+  @override
1981	+  int get hashCode => Object.hash(date, Object.hashAll(entries));
1982	+
1983	+  @override
1984	+  String toString() =>
1985	+      'EntryDateGroup(date: $date, entries: ${entries.length})';
1986	+}
1987	+
1988	+/// Groups [entries] by their [Entry.occurredAt]'s local calendar day
1989	+/// (Boundaries: "never `createdAt`"). Pure Dart — no `package:flutter`
1990	+/// import (RNF06), since `entries/domain` must stay flutter-free.
1991	+///
1992	+/// Preserves [entries]' own relative order within each group, and orders
1993	+/// the returned groups by each one's first-encountered entry — callers
1994	+/// (`EntriesRepository.list()`/`MeusRegistrosCubit`) always pass entries
1995	+/// already newest-first, so that ordering alone already yields groups
1996	+/// newest-day-first with no separate sort step needed here.
1997	+///
1998	+/// An empty [entries] list yields an empty list of groups (the "zero
1999	+/// entries" edge case) — never a single empty group.
2000	+List<EntryDateGroup> groupEntriesByDate(List<Entry> entries) {
2001	+  final entriesByDay = <DateTime, List<Entry>>{};
2002	+  final dayOrder = <DateTime>[];
2003	+
2004	+  for (final entry in entries) {
2005	+    final occurredAt = DateTime.parse(entry.occurredAt).toLocal();
2006	+    final day = DateTime(occurredAt.year, occurredAt.month, occurredAt.day);
2007	+    final bucket = entriesByDay.putIfAbsent(day, () {
2008	+      dayOrder.add(day);
2009	+      return <Entry>[];
2010	+    });
2011	+    bucket.add(entry);
2012	+  }
2013	+
2014	+  return [
2015	+    for (final day in dayOrder)
2016	+      EntryDateGroup(date: day, entries: entriesByDay[day]!),
2017	+  ];
2018	+}
2019	+
2020	+bool _listEquals(List<Entry> a, List<Entry> b) {
2021	+  if (a.length != b.length) {
2022	+    return false;
2023	+  }
2024	+  for (var i = 0; i < a.length; i++) {
2025	+    if (a[i] != b[i]) {
2026	+      return false;
2027	+    }
2028	+  }
2029	+  return true;
2030	+}
